-- =====================================================================
--  MODULE 0 · First steps: a million log lines in one query
-- =====================================================================
--  Before building anything, feel the engine. ClickHouse generates,
--  parses and aggregates data at several hundred million rows per second
--  on one replica. Everything in this workshop is built from this idea:
--  the data is generated by SQL, inside the database.
-- =====================================================================


-- STEP 1 · Where am I?
SELECT version() AS clickhouse_version, getMacro('replica') AS replica, uptime() AS uptime_seconds;
-- Measured: 1 ms · 1 row read


-- STEP 2 · numbers(): a table of integers, as long as you want
SELECT number FROM numbers(5);
-- Measured: 1 ms · 5 rows read


-- STEP 3 · One million log lines, generated in one SELECT
--  Each line gets a level, a service and a duration, derived from the line number
--  with cityHash64 (deterministic: everyone gets the same lines).
SELECT
    toDateTime('2026-11-27 00:00:00', 'UTC') + intDiv(number, 12)                                   AS ts,
    ['api-gateway', 'checkout', 'payment', 'fraud-scoring'][1 + cityHash64(number, 's') % 4]          AS service,
    multiIf(cityHash64(number, 'l') % 1000 < 5, 'ERROR', cityHash64(number, 'l') % 1000 < 40, 'WARN', 'INFO') AS level,
    concat('request ', toString(number), ' served in ', toString(5 + cityHash64(number, 'd') % 300), ' ms') AS message
FROM numbers(1000000)
LIMIT 5;
-- Measured: 3 ms · 5 rows read


-- STEP 4 · ... and aggregated at once
SELECT
    service,
    level,
    count()                                                                      AS lines,
    round(avg(toUInt32(extract(message, 'in ([0-9]+) ms'))), 1)                  AS avg_ms
FROM
(
    SELECT
        ['api-gateway', 'checkout', 'payment', 'fraud-scoring'][1 + cityHash64(number, 's') % 4] AS service,
        multiIf(cityHash64(number, 'l') % 1000 < 5, 'ERROR', cityHash64(number, 'l') % 1000 < 40, 'WARN', 'INFO') AS level,
        concat('request ', toString(number), ' served in ', toString(5 + cityHash64(number, 'd') % 300), ' ms') AS message
    FROM numbers(1000000)
)
GROUP BY service, level
ORDER BY service, level;
-- Measured: 341 ms · 1 M rows read (7.6 MB)
-- What to look for: one million lines generated, parsed with a regular expression
-- and aggregated, in a few hundred milliseconds. Try numbers(10000000).


-- STEP 5 · Checkpoint
SELECT if((SELECT count() FROM numbers(1000000)) = 1000000, 'OK', 'KO') AS first_steps;
-- Measured: 3 ms · 1 M rows read (7.6 MB)
